import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = { w: 512, h: 320 };

  const aspect = atlasRect.w / atlasRect.h;
  const baseHeight = 1.6;
  const geometry = new THREE.PlaneGeometry(baseHeight * aspect, baseHeight);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const uOffset = atlasRect.x / atlasSize.w;
  const vOffset = 1.0 - (atlasRect.y + atlasRect.h) / atlasSize.h;
  const uScale = atlasRect.w / atlasSize.w;
  const vScale = atlasRect.h / atlasSize.h;

  const uvNode = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  material.colorNode = texture(map, uvNode);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'pricing-card-1-accent';

  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    mesh.onBeforeRender = null;
  };

  return mesh;
}
